// Generated by Omnintent 0.1.0 from omnintent.json. Do not edit; regenerate instead.
//
// Per-user sign-in (SPEC.md, section E.5). This Worker is an OAuth 2.1
// authorization server for MCP clients and the protected resource at /mcp:
//
// 1. An MCP client calls /mcp without a token and gets 401 with a pointer to
//    the Protected Resource Metadata (RFC 9728), then registers (Client ID
//    Metadata Document or Dynamic Client Registration) and opens /authorize.
// 2. /authorize shows a consent page: which app is asking, where the access
//    goes, and what it may do. "See your data" (mcp:read) is always granted;
//    "Make changes" (mcp:write) can be unticked for a read-only grant.
// 3. After "Allow", the user signs in to the backend's own OAuth server (with
//    PKCE). The backend's token for that user is stored encrypted with the grant.
// 4. The MCP client gets its own token, bound to this server's /mcp URL. Tool
//    calls use the user's backend token; the MCP token never leaves this server.
//
// Hostnames are not hard-coded: MCP_SERVER_URL is this Worker's public origin.

import {
  AuthorizationError,
  CimdFetchError,
  GrantType,
  OAuthError,
  OAuthProvider,
  authorizationErrorRedirect,
  insufficientScope,
  type AuthRequest,
  type ConsentDescription,
  type OAuthHelpers,
  type OAuthResourceContext,
  type TokenExchangeCallbackOptions,
  type TokenExchangeCallbackResult,
} from "@cloudflare/workers-oauth-provider";
import { createMcpHandler } from "agents/mcp/server";
import { createServer, type Env } from "./server.ts";
import { APP, TOOLS } from "./tools.ts";
import type { BackendOAuth } from "./types.ts";

export const READ_SCOPE = "mcp:read";
export const WRITE_SCOPE = "mcp:write";

/** Stored encrypted with each grant; tools read it as ctx.props. */
export interface UserProps {
  userId: string;
  backend: BackendTokens;
}

interface BackendTokens {
  accessToken: string;
  refreshToken?: string;
  /** Unix time in seconds. */
  expiresAt?: number;
}

interface Config {
  serverUrl: string;
  oauth: BackendOAuth;
  clientId: string;
  clientSecret: string;
  backendBaseUrl: string;
}

/** Refresh the backend token when it has less than this many seconds left. */
const REFRESH_MARGIN_SECONDS = 300;
const MAX_ACCESS_TOKEN_SECONDS = 3600;

const BACKEND_AUTH = APP.backend.auth as BackendOAuth;

// ---------------------------------------------------------------- entry point

let cached: { key: string; provider: OAuthProvider<Env> } | undefined;

export async function handleRequest(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  const config = readConfig(env);
  if (typeof config === "string") return configError(config);
  const key = config.serverUrl;
  if (cached?.key !== key) cached = { key, provider: createProvider(config.serverUrl) };
  return cached.provider.fetch(request, env, ctx);
}

function createProvider(serverUrl: string): OAuthProvider<Env> {
  return new OAuthProvider<Env>({
    apiRoute: "/mcp",
    apiHandler: { fetch: handleMcp },
    defaultHandler: { fetch: handleDefault },
    authorizeEndpoint: `${serverUrl}/authorize`,
    tokenEndpoint: `${serverUrl}/oauth/token`,
    // Deprecated in MCP 2026-07-28 but still what many clients use.
    clientRegistrationEndpoint: `${serverUrl}/oauth/register`,
    clientIdMetadataDocumentEnabled: true,
    scopesSupported: [READ_SCOPE, WRITE_SCOPE],
    requiredScopes: [READ_SCOPE],
    accessTokenTTL: MAX_ACCESS_TOKEN_SECONDS,
    resourceMetadata: {
      resource: `${serverUrl}/mcp`,
      authorization_servers: [serverUrl],
      resource_name: APP.name,
    },
    tokenExchangeCallback: (options) => refreshBackendTokens(options),
  });
}

function readConfig(env: Env): Config | string {
  const raw = str(env.MCP_SERVER_URL);
  if (!raw) return "Set MCP_SERVER_URL to this server's public origin, for example https://<worker>.<subdomain>.workers.dev.";
  let serverUrl: URL;
  try {
    serverUrl = new URL(raw);
  } catch {
    return "MCP_SERVER_URL is not a URL.";
  }
  if (serverUrl.pathname !== "/" || serverUrl.search || serverUrl.hash) {
    return "MCP_SERVER_URL must be an origin only, with no path, for example https://mcp.example.com.";
  }
  if (!env.OAUTH_KV) return "Bind a KV namespace as OAUTH_KV (see wrangler.jsonc).";
  const oauth: BackendOAuth = {
    ...BACKEND_AUTH,
    authorizationUrl: str(env.BACKEND_OAUTH_AUTHORIZATION_URL) || BACKEND_AUTH.authorizationUrl,
    tokenUrl: str(env.BACKEND_OAUTH_TOKEN_URL) || BACKEND_AUTH.tokenUrl,
  };
  if (!isHttpUrl(oauth.authorizationUrl)) return "Set BACKEND_OAUTH_AUTHORIZATION_URL to the backend's OAuth authorization URL.";
  if (!isHttpUrl(oauth.tokenUrl)) return "Set BACKEND_OAUTH_TOKEN_URL to the backend's OAuth token URL.";
  const clientId = str(env.BACKEND_OAUTH_CLIENT_ID);
  if (!clientId) return "Set the BACKEND_OAUTH_CLIENT_ID secret.";
  const clientSecret = str(env.BACKEND_OAUTH_CLIENT_SECRET);
  if (!clientSecret && oauth.tokenAuthMethod !== "none") return "Set the BACKEND_OAUTH_CLIENT_SECRET secret.";
  const backendBaseUrl = (str(env.BACKEND_BASE_URL) || APP.backend.baseUrl).replace(/\/+$/, "");
  if (!isHttpUrl(backendBaseUrl)) return "Set BACKEND_BASE_URL to the backend's URL.";
  return { serverUrl: serverUrl.origin, oauth, clientId, clientSecret, backendBaseUrl };
}

// ---------------------------------------------------------------- /mcp (signed in)

async function handleMcp(request: Request, env: Env, executionCtx: ExecutionContext): Promise<Response> {
  // The provider only calls this with a valid token, and sets what it verified.
  const ctx = executionCtx as OAuthResourceContext<UserProps>;
  const needed = request.method === "POST" ? await scopesFor(request.clone()) : [READ_SCOPE];
  if (!needed.every((scope) => ctx.auth.scope.includes(scope))) return insufficientScope(ctx.auth, needed);
  const user = { backendToken: ctx.props.backend.accessToken };
  const handler = createMcpHandler(() => createServer(env, fetch, user), { route: "/mcp" });
  return handler(request, env, ctx);
}

/** Read tools need mcp:read; every other tool also needs mcp:write. */
async function scopesFor(request: Request): Promise<string[]> {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return [READ_SCOPE];
  }
  const messages = Array.isArray(body) ? body : [body];
  for (const message of messages) {
    if (!isRecord(message) || message.method !== "tools/call") continue;
    const params = message.params;
    if (!isRecord(params)) continue;
    const tool = TOOLS.find((t) => t.name === params.name);
    if (tool && tool.safety !== "read") return [READ_SCOPE, WRITE_SCOPE];
  }
  return [READ_SCOPE];
}

// ---------------------------------------------------------------- sign-in pages

async function handleDefault(request: Request, env: Env): Promise<Response> {
  const config = readConfig(env) as Config;
  const oauth = env.OAUTH_PROVIDER as OAuthHelpers;
  const url = new URL(request.url);
  try {
    if (url.pathname === "/") return Response.json({ name: APP.name, mcp: "/mcp" });
    if (url.pathname === "/authorize" && request.method === "GET") return await showConsent(request, env, oauth, config);
    if (url.pathname === "/authorize" && request.method === "POST") return await answerConsent(request, env, oauth, config);
    if (url.pathname === "/oauth/callback" && request.method === "GET") return await finishSignIn(request, oauth, config);
    return new Response("Not found", { status: 404 });
  } catch (error) {
    if (error instanceof AuthorizationError && error.redirectTo) return Response.redirect(error.redirectTo, 302);
    if (error instanceof AuthorizationError) return messagePage(400, "Sign-in could not continue", error.description || "Start signing in again from your app.");
    if (error instanceof CimdFetchError) return messagePage(400, "Sign-in could not continue", "This app could not be verified.");
    if (error instanceof SignInError) return messagePage(502, "Sign-in failed", error.message);
    throw error;
  }
}

async function showConsent(request: Request, env: Env, oauth: OAuthHelpers, config: Config): Promise<Response> {
  const authRequest = await oauth.parseAuthRequest(request);
  const remember = rememberOptions(env);
  if (remember && (await oauth.isConsentRemembered(request, authRequest, remember))) {
    return startBackendSignIn(oauth, config, authRequest, new Headers());
  }
  const details = await oauth.describeConsent(authRequest);
  const consent = await oauth.beginConsent(authRequest);
  consent.headers.set("content-type", "text/html; charset=utf-8");
  return new Response(consentPage(details, consent.handle), { headers: consent.headers });
}

async function answerConsent(request: Request, env: Env, oauth: OAuthHelpers, config: Config): Promise<Response> {
  const form = await request.formData();
  const handle = String(form.get("handle") ?? "");
  if (form.get("decision") !== "approve") {
    const denied = await oauth.denyConsent(request, handle);
    return new Response(null, { status: 302, headers: denied.headers });
  }
  const chosen = form.getAll("scope").map(String);
  const scope = [READ_SCOPE, ...(chosen.includes(WRITE_SCOPE) ? [WRITE_SCOPE] : [])];
  const remember = rememberOptions(env);
  const approved = await oauth.approveConsent(request, handle, { scope, ...(remember ? { remember } : {}) });
  return startBackendSignIn(oauth, config, approved.request, approved.headers);
}

/** Send the browser to the backend's own sign-in, with PKCE. */
async function startBackendSignIn(oauth: OAuthHelpers, config: Config, authRequest: AuthRequest, headers: Headers): Promise<Response> {
  const verifier = randomToken();
  const upstream = await oauth.beginUpstream(authRequest, { data: { verifier }, headers });
  const target = new URL(config.oauth.authorizationUrl);
  target.searchParams.set("response_type", "code");
  target.searchParams.set("client_id", config.clientId);
  target.searchParams.set("redirect_uri", `${config.serverUrl}/oauth/callback`);
  if (config.oauth.scopes.length) target.searchParams.set("scope", config.oauth.scopes.join(" "));
  target.searchParams.set("state", upstream.state);
  target.searchParams.set("code_challenge", await s256(verifier));
  target.searchParams.set("code_challenge_method", "S256");
  upstream.headers.set("location", target.toString());
  return new Response(null, { status: 302, headers: upstream.headers });
}

/** The backend sent the user back: exchange its code, find the user, finish the MCP grant. */
async function finishSignIn(request: Request, oauth: OAuthHelpers, config: Config): Promise<Response> {
  const resumed = await oauth.finishUpstream<{ verifier: string }>(request);
  const params = new URL(request.url).searchParams;
  const code = params.get("code");
  if (params.get("error") || !code) {
    resumed.headers.set("location", authorizationErrorRedirect(resumed.request, "access_denied"));
    return new Response(null, { status: 302, headers: resumed.headers });
  }
  const tokens = await requestBackendTokens(config, {
    grant_type: "authorization_code",
    code,
    redirect_uri: `${config.serverUrl}/oauth/callback`,
    code_verifier: resumed.data.verifier,
  });
  if (!tokens.ok) throw new SignInError(`The backend did not accept the sign-in (${tokens.error}).`);
  const userId = await fetchUserId(config, tokens.value.accessToken);
  const props: UserProps = { userId, backend: tokens.value };
  const { redirectTo } = await oauth.completeAuthorization({
    request: resumed.request,
    // Grant keys use ":" as a separator, so the ID is encoded.
    userId: encodeURIComponent(userId),
    metadata: {},
    scope: resumed.request.scope,
    props,
  });
  resumed.headers.set("location", redirectTo);
  return new Response(null, { status: 302, headers: resumed.headers });
}

async function fetchUserId(config: Config, accessToken: string): Promise<string> {
  let response: Response;
  try {
    response = await fetch(config.backendBaseUrl + config.oauth.userInfoPath, {
      headers: { accept: "application/json", authorization: `Bearer ${accessToken}` },
      signal: AbortSignal.timeout(APP.backend.timeoutMs),
    });
  } catch {
    throw new SignInError("The backend could not be reached to look up the signed-in user.");
  }
  if (!response.ok) throw new SignInError(`The backend refused the user lookup (${response.status}).`);
  const id = jsonPointer(await response.json().catch(() => undefined), config.oauth.userIdPointer);
  if ((typeof id !== "string" && typeof id !== "number") || String(id) === "") {
    throw new SignInError(`The user lookup response has no ID at ${config.oauth.userIdPointer}.`);
  }
  return String(id);
}

// ---------------------------------------------------------------- backend tokens

type TokenResult = { ok: true; value: BackendTokens } | { ok: false; error: string; status: number };

async function requestBackendTokens(config: Config, params: Record<string, string>): Promise<TokenResult> {
  const body = new URLSearchParams(params);
  const headers: Record<string, string> = {
    accept: "application/json",
    "content-type": "application/x-www-form-urlencoded",
  };
  if (config.oauth.tokenAuthMethod === "client_secret_basic") {
    headers.authorization = `Basic ${btoa(`${formEncode(config.clientId)}:${formEncode(config.clientSecret)}`)}`;
  } else {
    body.set("client_id", config.clientId);
    if (config.oauth.tokenAuthMethod === "client_secret_post") body.set("client_secret", config.clientSecret);
  }
  let response: Response;
  try {
    response = await fetch(config.oauth.tokenUrl, { method: "POST", headers, body, signal: AbortSignal.timeout(APP.backend.timeoutMs) });
  } catch {
    return { ok: false, error: "unreachable", status: 0 };
  }
  const data: unknown = await response.json().catch(() => undefined);
  if (!response.ok || !isRecord(data) || typeof data.access_token !== "string" || !data.access_token) {
    const error = isRecord(data) && typeof data.error === "string" ? data.error : `HTTP ${response.status}`;
    return { ok: false, error, status: response.status };
  }
  const expiresIn = Number(data.expires_in);
  return {
    ok: true,
    value: {
      accessToken: data.access_token,
      ...(typeof data.refresh_token === "string" && data.refresh_token ? { refreshToken: data.refresh_token } : {}),
      ...(Number.isFinite(expiresIn) && expiresIn > 0 ? { expiresAt: now() + Math.floor(expiresIn) } : {}),
    },
  };
}

/**
 * Runs when an MCP client exchanges a code or refreshes its token. Keeps the
 * MCP token no longer-lived than the backend token, and refreshes the backend
 * token when it is about to expire. A revoked backend grant revokes this one.
 */
async function refreshBackendTokens(options: TokenExchangeCallbackOptions<Env>): Promise<TokenExchangeCallbackResult | void> {
  const props = options.props as UserProps;
  if (options.grantType === GrantType.AUTHORIZATION_CODE) return lifetime(props.backend);
  if (options.grantType !== GrantType.REFRESH_TOKEN) return;
  const backend = props.backend;
  if (!backend.expiresAt || backend.expiresAt - now() > REFRESH_MARGIN_SECONDS) return lifetime(backend);
  if (!backend.refreshToken) {
    throw new OAuthError("invalid_grant", { description: "The backend sign-in expired. Sign in again." });
  }
  const config = readConfig(options.env);
  if (typeof config === "string") throw new OAuthError("temporarily_unavailable", { description: config, statusCode: 503 });
  const refreshed = await requestBackendTokens(config, { grant_type: "refresh_token", refresh_token: backend.refreshToken });
  if (!refreshed.ok) {
    if (refreshed.error === "invalid_grant" || refreshed.status === 400 || refreshed.status === 401) {
      throw new OAuthError("invalid_grant", { description: "The backend sign-in was revoked. Sign in again." });
    }
    throw new OAuthError("temporarily_unavailable", { description: "The backend is unavailable.", statusCode: 503 });
  }
  const next: BackendTokens = { ...refreshed.value, refreshToken: refreshed.value.refreshToken ?? backend.refreshToken };
  return { newProps: { ...props, backend: next } satisfies UserProps, ...lifetime(next) };
}

function lifetime(backend: BackendTokens): TokenExchangeCallbackResult {
  if (!backend.expiresAt) return {};
  const left = backend.expiresAt - now() - 30;
  return { accessTokenTTL: Math.max(60, Math.min(MAX_ACCESS_TOKEN_SECONDS, left)) };
}

// ---------------------------------------------------------------- pages

function consentPage(details: ConsentDescription, handle: string): string {
  const client = escapeHtml(details.clientName);
  const origin = details.clientDomain
    ? `Published by <strong>${escapeHtml(details.clientDomain)}</strong>.`
    : "This app registered itself, so its name is not verified.";
  const loopback = details.redirectIsLoopback
    ? "<p class=warn><strong>Access goes to an app on this computer.</strong> Continue only if you just started signing in from it.</p>"
    : "";
  const readTools = TOOLS.filter((t) => t.safety === "read").map((t) => t.title);
  const writeTools = TOOLS.filter((t) => t.safety !== "read").map((t) => t.title);
  const scopeRow = (scope: string, label: string, tools: string[], checked: boolean, locked: boolean) =>
    `<label><input type=checkbox name=scope value="${scope}"${checked ? " checked" : ""}${locked ? " disabled" : ""}> ${label}` +
    (tools.length ? `<br><small>${escapeHtml(tools.join(", "))}</small>` : "") +
    "</label>";
  return `<!doctype html>
<html lang=en>
<meta charset=utf-8>
<meta name=viewport content="width=device-width, initial-scale=1">
<title>Allow ${client}?</title>
<style>${PAGE_STYLE}</style>
<main>
<h1>Allow ${client} to use ${escapeHtml(APP.name)}?</h1>
<p>${origin} Access will be sent to <strong>${escapeHtml(details.redirectHost)}</strong>.</p>
${loopback}
<form method=post>
<input type=hidden name=handle value="${escapeHtml(handle)}">
<fieldset>
<legend>It will be able to</legend>
${scopeRow(READ_SCOPE, "See your data", readTools, true, true)}
${writeTools.length ? scopeRow(WRITE_SCOPE, "Make changes for you", writeTools, true, false) : ""}
</fieldset>
<p>Next, you will sign in to ${escapeHtml(APP.name)}.</p>
<p><button name=decision value=approve>Allow</button> <button name=decision value=deny class=secondary>Deny</button></p>
</form>
</main>
`;
}

function messagePage(status: number, title: string, message: string): Response {
  const html = `<!doctype html>
<html lang=en>
<meta charset=utf-8>
<meta name=viewport content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${PAGE_STYLE}</style>
<main><h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p></main>
`;
  return new Response(html, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "content-security-policy": "frame-ancestors 'none'",
      "x-frame-options": "DENY",
    },
  });
}

const PAGE_STYLE =
  "body{font:16px/1.5 system-ui,sans-serif;margin:0;padding:24px 16px;color:#1a1a1a;background:#fafafa}" +
  "main{max-width:32rem;margin:0 auto}h1{font-size:1.4rem}fieldset{border:1px solid #ccc;border-radius:8px}" +
  "label{display:block;margin:.5rem 0}small{color:#555;margin-left:1.6rem}.warn{background:#fff4d6;padding:8px;border-radius:6px}" +
  "button{font:inherit;padding:.5rem 1.2rem;border-radius:6px;border:0;background:#1a1a1a;color:#fff}" +
  "button.secondary{background:#e5e5e5;color:#1a1a1a}" +
  "@media (prefers-color-scheme:dark){body{background:#161616;color:#eee}small{color:#aaa}.warn{background:#4a3b10}" +
  "button{background:#eee;color:#111}button.secondary{background:#333;color:#eee}}";

function configError(message: string): Response {
  return Response.json({ error: "server_misconfigured", message }, { status: 500 });
}

// ---------------------------------------------------------------- helpers

class SignInError extends Error {}

function rememberOptions(env: Env): { secret: string } | undefined {
  const secret = str(env.CONSENT_SECRET);
  return secret.length >= 32 ? { secret } : undefined;
}

function randomToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  return base64Url(bytes);
}

async function s256(value: string): Promise<string> {
  return base64Url(new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value))));
}

function base64Url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** RFC 6749 section 2.3.1: client credentials are form-encoded before Basic. */
function formEncode(value: string): string {
  return encodeURIComponent(value).replace(/%20/g, "+");
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

function jsonPointer(value: unknown, pointer: string): unknown {
  if (pointer === "" || pointer === "/") return value;
  let current = value;
  for (const raw of pointer.slice(1).split("/")) {
    const key = raw.replace(/~1/g, "/").replace(/~0/g, "~");
    if (Array.isArray(current)) current = current[Number(key)];
    else if (isRecord(current)) current = current[key];
    else return undefined;
  }
  return current;
}

function str(value: unknown): string {
  return typeof value === "string" ? value.trim() : "";
}

function isHttpUrl(value: string): boolean {
  return /^https?:\/\/[^<>\s]+$/.test(value);
}

function now(): number {
  return Math.floor(Date.now() / 1000);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
